static uint64 xllm__memory_now_ms(void)
{
#ifdef _WIN32
    return (uint64)GetTickCount64();
#else
    struct timespec tNow;

    if ( clock_gettime(CLOCK_MONOTONIC, &tNow) != 0 ) {
        return 0u;
    }
    return ((uint64)tNow.tv_sec * 1000u) + (uint64)(tNow.tv_nsec / 1000000u);
#endif
}

